def get_network_proxy(name):
    proxies = json.loads(os.getenv("OUTGOING_HTTP_PROXY", "null") )   # {"http":"", "https": ""}
    if proxies:
        logger.info(f"Using network proxy - {proxies} in {name}")
        return httpx.Client(proxies=proxies)

    return proxies
